            <div className="text-sm font-semibold text-gray-700">
              AI Agent Query
            </div>
            <div className="text-xs text-gray-500">
              RAG: Pinecone + HuggingFace LLM
            </div>
          </div>
        </div>
        <div className="text-xs text-gray-400 mt-1">
          Context retrieval with conversational memory
        </div>
      </div>
    </EventNode>
