/**
 * Process Embeddings Event Step
 * Splits text, generates embeddings, and stores in Pinecone vector database
 */

import { EventConfig, Handlers } from 'motia';
import { z } from 'zod';
import { HarvestLogbookService } from '../../src/services/harvest-logbook';

const inputSchema = z.object({
  entryId: z.string(),
  content: z.string(),
  metadata: z.record(z.any()).optional()
});

export const config: EventConfig = {
  type: 'event',
  name: 'ProcessEmbeddings',
  description: 'Splits text into chunks, generates embeddings, and stores in vector database',
  subscribes: ['process-embeddings'],
  emits: [],
  input: inputSchema,
  flows: ['harvest-logbook']
};

export const handler: Handlers['ProcessEmbeddings'] = async (input, { logger, state }) => {
  try {
    const { entryId, content, metadata } = input;

    logger.info('Processing embeddings', {
      entryId,
      contentLength: content.length
    });

    // Store the entry using the service
    const vectorIds = await HarvestLogbookService.storeEntry({
      id: entryId,
      content,
      metadata,
      timestamp: new Date().toISOString()
    });

    // Update state with vector IDs
    await state.set('harvest-vectors', entryId, {
      vectorIds,
      processedAt: new Date().toISOString(),
      chunkCount: vectorIds.length
    });

    logger.info('Successfully processed and stored embeddings', {
      entryId,
      vectorCount: vectorIds.length
    });
  } catch (error) {
    logger.error('Failed to process embeddings', {
      entryId: input.entryId,
      error: error instanceof Error ? error.message : 'Unknown error'
    });
    throw error; // Re-throw to trigger retry mechanism
  }
};

/**
 * Query Only API Step
 * Separate endpoint for querying the harvest logbook without storing new data
 */

import { ApiRouteConfig, Handlers } from 'motia';
import { z } from 'zod';
import { harvestQueryMiddleware } from '../../middlewares/authz.middleware';
import { errorHandlerMiddleware } from '../../middlewares/error-handler.middleware';

const bodySchema = z.object({
  query: z.string().min(1, 'Query cannot be empty'),
  farmId: z.string().min(1, 'Farm ID is required for authorization'),
  conversationHistory: z.array(z.object({
    role: z.enum(['user', 'assistant', 'system']),
    content: z.string()
  })).optional()
});

export const config: ApiRouteConfig = {
  type: 'api',
  name: 'QueryHarvestLogbook',
  description: 'Query the harvest logbook knowledge base without storing new data',
  path: '/harvest_logbook/query',
  method: 'POST',
  middleware: [errorHandlerMiddleware, harvestQueryMiddleware],
  emits: ['query-agent'],
  flows: ['harvest-logbook'],
  bodySchema,
  responseSchema: {
    200: z.object({
      success: z.boolean(),
      message: z.string(),
      queryId: z.string()
    }),
    400: z.object({ error: z.string() }),
    401: z.object({ error: z.string(), message: z.string() }),
    403: z.object({ error: z.string(), message: z.string() }),
    500: z.object({ error: z.string() })
  }
};

export const handler: Handlers['QueryHarvestLogbook'] = async (req, { emit, logger }) => {
  const { query, farmId, conversationHistory } = bodySchema.parse(req.body);

  const queryId = `query-${Date.now()}`;

  // Authorization info is available from middleware
  const userId = (req as any).authz?.userId;

  logger.info('Received query for harvest logbook', {
    queryId,
    farmId,
    userId,
    queryLength: query.length
  });

  // Trigger agent query
  await emit({
    topic: 'query-agent',
    data: {
      entryId: queryId,
      query,
      conversationHistory: conversationHistory || []
    }
  });

  return {
    status: 200,
    body: {
      success: true,
      message: 'Query initiated',
      queryId
    }
  };
};
